const MAX_ARTICLES = 8;
const MAX_PER_SOURCE = 3;
const user = $('Get user').first().json;
const interests = (user.interests || '').split(',').map(i => i.trim()).filter(Boolean);

const ranked = $input.all()
  .map(item => item.json)
  .filter(article => article.id)
  .map(article => ({
    ...article,
    matches: (article.categories || '').split(',').filter(c => interests.includes(c)).length,
  }))
  .filter(article => article.matches > 0)
  .sort((a, b) => b.matches - a.matches || new Date(b.published_at) - new Date(a.published_at));

const perSource = {};
const articles = [];
for (const article of ranked) {
  perSource[article.source] = (perSource[article.source] || 0) + 1;
  if (perSource[article.source] > MAX_PER_SOURCE) continue;
  const { id, title, url, source, summary, categories, published_at } = article;
  articles.push({ id, title, url, source, summary, categories, published_at });
  if (articles.length === MAX_ARTICLES) break;
}

return [{ json: { user, articles } }];

const { user, articles } = $('Pick best articles').first().json;
const ai = $json.output;
const lang = ['fr', 'en'].includes(user.language) ? user.language : 'en';
const LABELS = {
  fr: { read: "Lire l'article", footer: 'Vous recevez cette newsletter car vous êtes inscrit. Pour vous désinscrire, écrivez « désinscription » au chatbot.' },
  en: { read: 'Read the article', footer: 'You receive this newsletter because you signed up. To unsubscribe, write "unsubscribe" to the chatbot.' },
};
const label = LABELS[lang];

const escape = (text) => String(text ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const safeUrl = (url) => (/^https?:\/\//i.test(url || '') ? url : '#');

const byId = new Map(articles.map(a => [a.id, a]));
const written = new Map((ai.items || []).filter(i => byId.has(i.id)).map(i => [i.id, i]));
const entries = [...written.keys(), ...articles.map(a => a.id).filter(id => !written.has(id))]
  .map(id => ({ ...byId.get(id), title: written.get(id)?.title || byId.get(id).title, summary: written.get(id)?.summary || byId.get(id).summary }));

const date = new Date().toLocaleDateString(lang, { weekday: 'long', day: 'numeric', month: 'long', timeZone: user.timezone || 'Europe/Paris' });

const cards = entries.map(a => `
  <tr><td style="padding:0 0 24px 0;">
    <p style="margin:0 0 6px 0;font:600 12px Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.06em;">${escape(a.source)} · ${escape(a.categories.split(',').join(' · '))}</p>
    <p style="margin:0 0 8px 0;font:700 18px/1.3 Georgia,serif;color:#111827;"><a href="${escape(safeUrl(a.url))}" style="color:#111827;text-decoration:none;">${escape(a.title)}</a></p>
    <p style="margin:0 0 10px 0;font:15px/1.55 Arial,sans-serif;color:#374151;">${escape(a.summary)}</p>
    <a href="${escape(safeUrl(a.url))}" style="font:600 14px Arial,sans-serif;color:#2f5bea;text-decoration:none;">${escape(label.read)} →</a>
  </td></tr>`).join('');

const html = `<!doctype html>
<html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(ai.subject)}</title></head>
<body style="margin:0;padding:0;background:#f3f4f6;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;"><tr><td align="center" style="padding:24px 12px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:8px;">
    <tr><td style="padding:28px 28px 8px 28px;">
      <p style="margin:0;font:700 22px Georgia,serif;color:#2f5bea;">NewsLetter</p>
      <p style="margin:4px 0 0 0;font:13px Arial,sans-serif;color:#6b7280;">${escape(date)}</p>
    </td></tr>
    <tr><td style="padding:12px 28px 20px 28px;font:16px/1.55 Arial,sans-serif;color:#111827;">${escape(ai.intro)}</td></tr>
    <tr><td style="padding:0 28px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${cards}</table></td></tr>
    <tr><td style="padding:16px 28px 28px 28px;border-top:1px solid #e5e7eb;font:12px/1.5 Arial,sans-serif;color:#6b7280;">${escape(label.footer)}</td></tr>
  </table>
</td></tr></table>
</body></html>`;

const text = [
  `${date}`, '', ai.intro, '',
  ...entries.map(a => `• ${a.title} (${a.source})\n  ${a.summary}\n  ${safeUrl(a.url)}\n`),
  '—', label.footer,
].join('\n');

return [{ json: { user_id: user.id, email: user.email, subject: ai.subject, html, text, article_ids: entries.map(a => a.id) } }];
